const items = $input.all();
if (items.length === 0) return [];

const business = $node["Get Active Businesses"].json;
let totalMin = 0, totalMax = 0;
let listHtml = '<ul>';

items.forEach(item => {
  const b = item.json;
  totalMin += parseFloat(b.quote_min || 0);
  totalMax += parseFloat(b.quote_max || 0);
  const time = new Date(b.scheduled_start).toLocaleTimeString('en-AU', { hour: 'numeric', minute: '2-digit' });
  listHtml += `<li><strong>${time}</strong>: ${b.service_name} (${b.customer_name || 'No Name'}) — Est. $${b.quote_min}-$${b.quote_max}</li>`;
});

listHtml += '</ul>';

return [{
  json: {
    business_name: business.business_name,
    provider_email: business.provider_email,
    total_count: items.length,
    total_min: totalMin,
    total_max: totalMax,
    list_html: listHtml
  }
}];
